// Synthetic only: the UI skin INI reader / writer and that configs/ui/default.ini (checked in, generated by the C++
// test) equals the editor's default tables.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
    HUD_ACCENT_DEFAULT,
    LAYOUT_KEYS,
    PAGES,
    THEME_COLORS,
    THEME_SIZES,
    TITLE_DESCRIPTIONS,
    buildUiSkinPackFiles,
    defaultString,
    emptySkin,
    labelKey,
    pageRows,
    parseUiSkin,
    serializeUiSkin,
    validateUiSkin,
} from '../src/index.ts';

describe('ui skin', () => {
    it('parses and round-trips', () => {
        const text =
            '[theme]\naccent = #20c0a0\nsize_body = 30\nbogus = 1\n[hud]\naccent = #FF00FF\n[layout]\ntitle_row_h = 70\n' +
            '[rows]\ntitle.main = new_game , quit,,\nnope = a\n[strings]\ntitle.row.new_game = Begin\\nAnew\n[wat]\nx = y\n';
        const { skin, warnings } = parseUiSkin(text);
        expect(warnings, warnings.join('|')).toHaveLength(3); // bogus key, unknown row page, unknown section
        expect(skin.colors['accent']).toBe('#20C0A0');
        expect(skin.colors['hud_accent']).toBe('#FF00FF');
        expect(skin.numbers).toEqual({ size_body: 30, title_row_h: 70 });
        expect(skin.rows['title.main']).toEqual(['new_game', 'quit']);
        expect(skin.strings['title.row.new_game']).toBe('Begin\nAnew');
        const again = parseUiSkin(serializeUiSkin(skin)).skin;
        expect(again).toEqual(skin);
    });

    it('writes only what differs from the defaults', () => {
        const s = emptySkin();
        s.colors['accent'] = '#E07B2E';
        s.numbers['size_body'] = 24;
        s.rows['pause.root'] = PAGES[1]!.rows.map((r) => r.id);
        s.strings['pause.row.resume'] = 'Resume';
        expect(serializeUiSkin(s)).toBe('');
        s.strings['pause.row.resume'] = 'Return';
        expect(serializeUiSkin(s)).toBe('[strings]\npause.row.resume = Return\n');
    });

    it('orders and hides rows', () => {
        const s = emptySkin();
        s.rows['pause.root'] = ['options', 'resume'];
        const rows = pageRows(s, PAGES[1]!);
        expect(rows.filter((x) => x.shown).map((x) => x.row.id)).toEqual(['options', 'resume']);
        expect(rows.filter((x) => !x.shown).map((x) => x.row.id)).toEqual(['save', 'load', 'quit']);
        expect(validateUiSkin(s)).toEqual([]);
        s.rows['title.main'] = ['new_game'];
        expect(validateUiSkin(s)[0]).toMatch(/Quit is hidden/);
    });

    it('builds a pack with ui/menus.ini', () => {
        const s = emptySkin();
        s.strings['title.row.quit'] = 'Leave';
        const files = buildUiSkinPackFiles(s, { id: 'menus.demo', target: { profile: '*' } });
        expect(Object.keys(files).sort()).toEqual(['mod.toml', 'ui/menus.ini']);
        expect(new TextDecoder().decode(files['ui/menus.ini'])).toContain('title.row.quit = Leave');
    });

    it('configs/ui/default.ini matches the default tables', () => {
        const path = new URL('../../../../configs/ui/default.ini', import.meta.url);
        const { skin, warnings } = parseUiSkin(readFileSync(path, 'utf8'));
        expect(warnings).toEqual([]);
        for (const c of THEME_COLORS) expect(skin.colors[c.key], c.key).toBe(c.def);
        expect(skin.colors['hud_accent']).toBe(HUD_ACCENT_DEFAULT);
        for (const n of [...THEME_SIZES, ...LAYOUT_KEYS]) expect(String(skin.numbers[n.key]), n.key).toBe(n.def);
        for (const p of PAGES) expect(skin.rows[p.id], p.id).toEqual(p.rows.map((r) => r.id));
        for (const p of PAGES)
            for (const r of p.rows)
                expect(skin.strings[labelKey(p.id, r.id)], r.id).toBe(defaultString(labelKey(p.id, r.id)));
        for (const [id, text] of Object.entries(TITLE_DESCRIPTIONS))
            expect(skin.strings[`title.desc.${id}`]).toBe(text);
        expect(skin.strings['title.quit.title']).toBe('Quit the game?');
    });
});
